import { index, integer, jsonb, pgTable, primaryKey, text, timestamp, uuid } from 'drizzle-orm/pg-core';

// Tables are unqualified on purpose: the connection's search_path decides the
// schema ("orders" in the service, "orders_test" in tests).

export const orders = pgTable(
  'orders',
  {
    // Generated by the caller and used as the idempotency key of the submit.
    id: uuid('id').primaryKey(),
    // Ids owned by identity; no foreign keys across services.
    sellerId: text('seller_id').notNull(),
    clientId: text('client_id').notNull(),
    priceTableId: text('price_table_id').notNull(),
    // SUBMITTED | AWAITING_APPROVAL
    status: text('status').notNull(),
    subtotalCents: integer('subtotal_cents').notNull(),
    orderDiscountBp: integer('order_discount_bp').notNull(),
    orderDiscountCents: integer('order_discount_cents').notNull(),
    totalCents: integer('total_cents').notNull(),
    // Why the order needed approval, as calculated at submit time.
    approvalReasons: jsonb('approval_reasons').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index('orders_seller_created_idx').on(table.sellerId, table.createdAt),
    index('orders_client_created_idx').on(table.clientId, table.createdAt),
  ],
);

// What was sold, as it was at submit time: product data and prices are copied,
// never looked up again.
export const orderItems = pgTable(
  'order_items',
  {
    orderId: uuid('order_id')
      .notNull()
      .references(() => orders.id),
    productId: text('product_id').notNull(),
    sku: text('sku').notNull(),
    description: text('description').notNull(),
    // How the seller entered the quantity: UNIT or PACK.
    unit: text('unit').notNull(),
    quantityInput: integer('quantity_input').notNull(),
    quantityUnits: integer('quantity_units').notNull(),
    packFactor: integer('pack_factor').notNull(),
    unitPriceCents: integer('unit_price_cents').notNull(),
    discountBp: integer('discount_bp').notNull(),
    grossCents: integer('gross_cents').notNull(),
    netCents: integer('net_cents').notNull(),
  },
  // One line per product, enforced by the database as well as by the rules.
  (table) => [primaryKey({ columns: [table.orderId, table.productId] })],
);
